CREATE TABLE IF NOT EXISTS prov_proveedor_contactos (
 clave VARCHAR(255) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
 telefono VARCHAR(120) NOT NULL DEFAULT '',
 correos JSON NOT NULL,
 correo_original VARCHAR(500) NOT NULL DEFAULT '',
 direccion TEXT NOT NULL,
 condicion_pago VARCHAR(10) NULL,
 actualizado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB;
ON DUPLICATE KEY UPDATE telefono=VALUES(telefono), correos=VALUES(correos), correo_original=VALUES(correo_original), direccion=VALUES(direccion), condicion_pago=VALUES(condicion_pago);
